def first_long_word(text, k):
    for word in text.split():
        if len(word) >= k:
            return word
    return ""

def edge_swap(values):
    result = values[:]
    if len(result) >= 2:
        result[0], result[-1] = result[-1], result[0]
    return result

values = list(map(int, input().split()))
count = 0
for i in range(1, len(values)):
    if values[i] != values[i - 1]:
        count += 1
print(count)
